"""Lock the app's runtime packages to one macOS 14 wheel each, by sha256."""

import argparse
import json
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
HEADER = """\
# The standalone app's runtime packages: CPython 3.12, Apple silicon, macOS 14.
# One wheel per package, by sha256, so every build installs the same files
# whatever macOS builds it. Generated by launcher/macos/Tools/lock_runtime.py from
# backend/requirements.txt and backend/constraints/macos-arm64.txt; do not edit.
"""


def lock_lines(report):
    lines = []
    for item in report['install']:
        name, version = item['metadata']['name'], item['metadata']['version']
        url = item['download_info']['url']
        sha = item['download_info'].get('archive_info', {}).get('hashes', {}).get('sha256')
        if not url.endswith('.whl') or not sha:
            raise ValueError(f'{name} resolved to something other than a hashed wheel')
        lines.append(f'{name}=={version} --hash=sha256:{sha}')
    return sorted(lines, key=str.lower)


def resolve(root):
    with tempfile.TemporaryDirectory(prefix='roleband-runtime-lock-') as directory:
        report = Path(directory) / 'report.json'
        subprocess.run([sys.executable, '-m', 'pip', '--isolated', 'install', '--disable-pip-version-check',
                        '--dry-run', '--ignore-installed', '--only-binary=:all:', '--platform', 'macosx_14_0_arm64', '--python-version', '3.12',
                        '--implementation', 'cp', '--abi', 'cp312', '--target', str(Path(directory) / 'target'),
                        '--report', str(report), '--quiet',
                        '-c', str(root / 'backend/constraints/macos-arm64.txt'),
                        '-r', str(root / 'backend/requirements.txt'), 'setuptools'], check=True)
        return json.loads(report.read_text())


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.parse_args()
    lock = ROOT / 'launcher/macos/runtime-lock.txt'
    lock.write_text(HEADER + '\n'.join(lock_lines(resolve(ROOT))) + '\n')
    print(lock)


if __name__ == '__main__':
    main()
